const errorData = $json;
const processedAt = new Date().toISOString();

const logEntry = {
  run_id: errorData.execution?.id || 'error-run-' + Date.now(),
  candidate_id: 'UNKNOWN_OR_ERROR',
  step: 'WORKFLOW_ERROR',
  status: 'ERROR',
  input_ref: errorData.workflow?.name || 'HR Screening 4 Lớp',
  output_ref: 'Run Log Tab (Error)',
  schema_validation: 'FAIL',
  error_code: errorData.execution?.error?.name || 'EXECUTION_ERROR',
  error_message: errorData.execution?.error?.message || 'Workflow execution encountered an unexpected error.',
  processed_at: processedAt
};

return [{ json: logEntry }];
